paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\": \"\"} -->\n<div class=\"wp-block-group \"><!-- wp:shortcode -->\n[atelier_booking]\n<!-- /wp:shortcode -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n"], "privacy-policy": ["Privacy policy", "<section class=\"section prose\"><p><strong>Starter privacy notice — customize before publishing.</strong></p><h2>Appointment requests</h2><p>When you request an appointment, your name, email, optional phone number, preferred service, date, time, and message are sent to the salon by email. We use these details to respond to your request.</p><h2>Data handling</h2><p>The theme does not create a separate appointment database. Requests may be retained in the salon’s email system and by any mail delivery plugins or services you configure. A hashed visitor network address is temporarily stored for one minute to limit repeated requests.</p><h2>Your choices</h2><p>Add your business identity, privacy contact, applicable rights, retention periods, hosting and email providers, and any analytics or cookies used by your installation. Review WordPress’s privacy policy guidance for site-specific details.</p></section>"], "cut-finish": ["Cut & finish", "<!-- wp:group {\"tagName\": \"section\", \"className\": \"section service-detail-hero\"} -->\n<section class=\"wp-block-group section service-detail-hero\"><!-- wp:group {\"className\": \"service-detail-intro\"} -->\n<div class=\"wp-block-group service-detail-intro\"><!-- wp:paragraph {\"className\": \"eyebrow\"} -->\n<p class=\"eyebrow\">THE ATELIER MENU / CUT &AMP; FINISH</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\": 2} -->\n<h2 class=\"wp-block-heading\">A shape that’s<br><em>entirely yours.</em></h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\": \"service-detail-lead\"} -->\n<p class=\"service-detail-lead\">From a subtle refresh to a new silhouette, a thoughtful cut begins with the way you live — and the way your hair naturally m