eading\">Your visit,<br><em>considered.</em></h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>For a maintenance trim, a fresh shape, or a change you’ve been considering.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\": \"ritual-grid\"} -->\n<div class=\"wp-block-group ritual-grid\"><!-- wp:group {\"className\": \"ritual-step\"} -->\n<div class=\"wp-block-group ritual-step\"><!-- wp:paragraph {\"className\": \"service-number\"} -->\n<p class=\"service-number\">01</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\": 3} -->\n<h3 class=\"wp-block-heading\">Listen</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>We talk about your routine, natural texture, and the shape you have in mind.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\": \"ritual-step\"} -->\n<div class=\"wp-block-group ritual-step\"><!-- wp:paragraph {\"className\": \"service-number\"} -->\n<p class=\"service-number\">02</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\": 3} -->\n<h3 class=\"wp-block-heading\">Shape</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Your stylist considers length, balance, and movement before refining the details.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\": \"ritual-step\"} -->\n<div class=\"wp-block-group ritual-step\"><!-- wp:paragraph {\"className\": \"service-number\"} -->\n<p class=\"service-number\">03</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\": 3} -->\n<h3 class=\"wp-block-heading\">Finish</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>A considered finish, with practical advice to recreate the feeling at home.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n<!-- wp:group {\"tagName\": \"section\", \"className\": \"section service-preparation\"} -->\n<section class=\"wp-block-group section service-preparation\"><!-- wp:group {\"className\": 