oup {\"className\": \"\"} -->\n<div class=\"wp-block-group \"><!-- wp:paragraph {\"className\": \"eyebrow\"} -->\n<p class=\"eyebrow\">APPOINTMENT</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>120–180 min</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\": \"\"} -->\n<div class=\"wp-block-group \"><!-- wp:paragraph {\"className\": \"eyebrow\"} -->\n<p class=\"eyebrow\">PRICING</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Confirmed by the salon</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph {\"className\": \"link-paragraph\"} -->\n<p class=\"link-paragraph\"><a class=\"button\" href=\"{{page:book-appointment}}\">Request this service ↗</a></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\": \"link-paragraph\"} -->\n<p class=\"link-paragraph\"><a class=\"text-link\" href=\"{{page:services}}\">← Back to all services</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\": \"service-detail-image\"} -->\n<div class=\"wp-block-group service-detail-image\"><!-- wp:image {\"sizeSlug\": \"full\", \"linkDestination\": \"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"{{asset:detail}}\" alt=\"Illustrative salon portrait; replace with your own business photograph\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n<!-- wp:group {\"tagName\": \"section\", \"className\": \"section service-experience\"} -->\n<section class=\"wp-block-group section service-experience\"><!-- wp:group {\"className\": \"section-title\"} -->\n<div class=\"wp-block-group section-title\"><!-- wp:paragraph {\"className\": \"eyebrow\"} -->\n<p class=\"eyebrow\">WHAT TO EXPECT</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\": 2} -->\n<h2 class=\"wp-block-heading\">Your visit,<br><em>considered.</em></h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>For softly blended dimension, brightn