group {\"tagName\": \"section\", \"className\": \"section service-detail-hero\"} -->\n<section class=\"wp-block-group section service-detail-hero\"><!-- wp:group {\"className\": \"service-detail-intro\"} -->\n<div class=\"wp-block-group service-detail-intro\"><!-- wp:paragraph {\"className\": \"eyebrow\"} -->\n<p class=\"eyebrow\">THE ATELIER MENU / SCALP &AMP; REPAIR</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\": 2} -->\n<h2 class=\"wp-block-heading\">A pause for you.<br><em>Care from the root.</em></h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\": \"service-detail-lead\"} -->\n<p class=\"service-detail-lead\">A restorative salon ritual focused on how your hair and scalp feel, with product choices guided by a conversation about your routine and concerns.</p>\n<!-- /wp:paragraph -->\n<!-- wp:group {\"className\": \"service-facts\"} -->\n<div class=\"wp-block-group service-facts\"><!-- wp:group {\"className\": \"\"} -->\n<div class=\"wp-block-group \"><!-- wp:paragraph {\"className\": \"eyebrow\"} -->\n<p class=\"eyebrow\">APPOINTMENT</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>45 min</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\": \"\"} -->\n<div class=\"wp-block-group \"><!-- wp:paragraph {\"className\": \"eyebrow\"} -->\n<p class=\"eyebrow\">PRICING</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Confirmed by the salon</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph {\"className\": \"link-paragraph\"} -->\n<p class=\"link-paragraph\"><a class=\"button\" href=\"{{page:book-appointment}}\">Request this service ↗</a></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\": \"link-paragraph\"} -->\n<p class=\"link-paragraph\"><a class=\"text-link\" href=\"{{page:services}}\">← Back to all services</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\": \"service-detail-image\"} -->\n<div class=\"