wp:group -->\n<!-- wp:group {\"className\": \"service-faq-list\"} -->\n<div class=\"wp-block-group service-faq-list\"><!-- wp:details -->\n<details class=\"wp-block-details\"><summary>Is a treatment included?</summary><!-- wp:paragraph -->\n<p>A consultation is a planning appointment unless the salon confirms otherwise. Request treatment time separately.</p>\n<!-- /wp:paragraph -->\n</details>\n<!-- /wp:details -->\n<!-- wp:details -->\n<details class=\"wp-block-details\"><summary>Will I receive a price estimate?</summary><!-- wp:paragraph -->\n<p>Ask the salon to provide an estimate and explain what could affect the final cost before booking a service.</p>\n<!-- /wp:paragraph -->\n</details>\n<!-- /wp:details -->\n<!-- wp:details -->\n<details class=\"wp-block-details\"><summary>Can I book my treatment afterwards?</summary><!-- wp:paragraph -->\n<p>Yes, subject to availability and any preparation or testing requirements discussed during your visit.</p>\n<!-- /wp:paragraph -->\n</details>\n<!-- /wp:details -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n<!-- wp:group {\"tagName\": \"section\", \"className\": \"section related-services\"} -->\n<section class=\"wp-block-group section related-services\"><!-- wp:group {\"className\": \"section-title horizontal\"} -->\n<div class=\"wp-block-group section-title horizontal\"><!-- wp:heading {\"level\": 2} -->\n<h2 class=\"wp-block-heading\">Continue<br><em>exploring.</em></h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\": \"link-paragraph\"} -->\n<p class=\"link-paragraph\"><a class=\"text-link\" href=\"{{page:services}}\">The complete service edit ↗</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\": \"related-grid\"} -->\n<div class=\"wp-block-group related-grid\"><!-- wp:group {\"className\": \"related-service\"} -->\n<div class=\"wp-block-group related-service\"><!-- wp:paragraph {\"className\": \"eyebrow\"} -->\n<p class=\"eyebrow\">THE ATELIER MENU</p